grid-template-columns: repeat(4, minmax(0, 1fr));
}
}
@container tw (max-width: 560px) {
.tw-mosaico {
grid-template-columns: repeat(3, minmax(0, 1fr));
gap: 8px;
padding: 10px;
}
.tw-mosaico > :nth-child(n+7) {
display: none;
}
}
.tw-tesela {
aspect-ratio: 3 / 4;
background: var(--color-hueso);
animation: tw-tesela .56s var(--ease-cayla) both;
animation-delay: calc(min(var(--i, 0), 14) * 45ms + .28s);
transition: transform .24s var(--ease-cayla), box-shadow .24s var(--ease-cayla);
border-radius: 12px;
display: block;
position: relative;
overflow: hidden;
}
.tw-tesela:focus-visible {
transform: translateY(-3px);
box-shadow: 0 12px 26px -16px #1a1a188c;
}
@supports (color: color-mix(in lab, red, red)) {
.tw-tesela:focus-visible {
box-shadow: 0 12px 26px -16px color-mix(in srgb, var(--color-sombra) 55%, transparent);
}
}
@media (hover: hover) {
.tw-tesela:hover {
transform: translateY(-3px);
box-shadow: 0 12px 26px -16px #1a1a188c;
}
@supports (color: color-mix(in lab, red, red)) {
.tw-tesela:hover {
box-shadow: 0 12px 26px -16px color-mix(in srgb, var(--color-sombra) 55%, transparent);
}
}
}
.tw-tesela > :first-child {
position: absolute;
inset: 0;
}
.tw-tesela-pie {
color: var(--color-crema-fija);
background: linear-gradient(to top, #1a1a18b8, #0000);
padding: 22px 9px 8px;
font-size: 14px;
font-weight: 500;
line-height: 1.25;
position: absolute;
inset: auto 0 0;
}
@supports (color: color-mix(in lab, red, red)) {
.tw-tesela-pie {
background: linear-gradient(to top, color-mix(in srgb, var(--color-tinta-fija) 72%, transparent), transparent);
}
}
.tw-tesela-pie {
text-overflow: ellipsis;
white-space: nowrap;
overflow: hidden;
}
.tw-tesela-sello {
letter-spacing: .08em;
text-transform: uppercase;
color: var(--color-tinta-fija);
background: #f5f0e8e6;
border-radius: 999px;
padding: 2px 7px;
font-size: 10px;
font-weight: 700;
position: absolute;
top: 7px;
left: 7px;
}
@supports (color: color-mix(in lab, red, red)) {
.tw-tesela-sello {
background: color-mix(in srgb, var(--color-crema-fija) 90%, transparent);
}
}
.tw-camino {
grid-template-columns: repeat(2, minmax(0, 1fr));
gap: 12px;
display: grid;
}
.tw-camino-tramo, .tw-camino-hueco {
display: none;
}
@media (min-width: 1280px) {
.tw-camino {
grid-template-columns: minmax(0, 1fr) 5.75rem minmax(0, 1fr) 5.75rem minmax(0, 1fr) 5.75rem minmax(0, 1fr);
align-items: stretch;
gap: 0;
}
.tw-camino-tramo {
flex-direction: column;
justify-content: center;
align-items: center;
gap: 4px;
padding: 0 4px;
display: flex;
}
.tw-camino-hueco {
display: block;
}
}
.tw-camino-tramo > svg {
width: 100%;
height: 16px;
display: block;
overflow: visible;
}
.tw-camino-linea {
fill: none;
stroke: var(--color-taupe);
stroke-width: 1.5px;
stroke-linecap: round;
stroke-dasharray: 1;
animation: tw-dibuja .7s var(--ease-cayla) both;
animation-delay: calc(var(--d, 0) * .16s + .42s);
}
.tw-camino-punta {
fill: var(--color-taupe);
transform-box: fill-box;
transform-origin: center;
animation: tw-asoma .36s var(--ease-cayla) both;
animation-delay: calc(var(--d, 0) * .16s + 1.02s);
}
.tw-camino-verbo {
color: var(--color-tinta);
text-align: center;
font-size: 14px;
font-weight: 600;
line-height: 1.1;
}
.tw-camino-plazo {
color: var(--color-taupe);
text-align: center;
text-wrap: balance;
justify-content: center;
align-items: flex-start;
gap: 3px;
font-size: 13px;
line-height: 1.2;
display: inline-flex;
}
.tw-camino-tramo:not([data-cierra]) .tw-camino-linea {
stroke-dasharray: .05 .07;
animation-name: tw-funde;
}
.tw-camino-tramo[data-cierra] .tw-camino-plazo {
color: var(--color-rojo-profundo);
font-weight: 600;
}
.tw-camino-verbo, .tw-camino-plazo {
animation: tw-entra .42s var(--ease-cayla) both;
animation-delay: calc(var(--d, 0) * .16s + .64s);
}
.tw-bandeja {
gap: 10px;
display: grid;
}
@container tw (min-width: 760px) {
.tw-bandeja {
grid-template-columns: repeat(2, minmax(0, 1fr));
}
}
.tw-pendiente {
--tono: var(--color-pizarra);
border: 1px solid var(--color-sand);
background: var(--color-papel);
animation: tw-entra .46s var(--ease-cayla) both;
animation-delay: calc(min(var(--i, 0), 12) * 55ms + .2s);
transition: border-color .2s var(--ease-cayla), transform .2s var(--ease-cayla), background-color .2s var(--ease-cayla);
border-radius: 14px;
grid-template-columns: 40px minmax(0, 1fr) auto;
align-items: center;
gap: 14px;
padding: 14px 16px 14px 18px;
display: grid;
position: relative;
overflow: hidden;
}
.tw-pendiente[data-tono="urgente"] {
--tono: var(--color-rojo-profundo);
}
.tw-pendiente[data-tono="atencion"] {
--tono: var(--color-ambar-profundo);
}
@media (hover: hover) {
.tw-pendiente:hover {
border-color: var(--color-taupe);
background: #f7f3eb;
transform: translateY(-1px);
}
@supports (color: color-mix(in lab, red, red)) {
.tw-pendiente:hover {
background: color-mix(in srgb, var(--color-sand) 22%, var(--color-papel));
}
}
}
.tw-pendiente:before {
content: "";
background: var(--tono);
transform-origin: top;
width: 3px;
animation: tw-crece-y .52s var(--ease-cayla) both;
animation-delay: calc(min(var(--i, 0), 12) * 55ms + .42s);
border-radius: 0 3px 3px 0;
position: absolute;
top: 12px;
bottom: 12px;
left: 0;
}
@keyframes tw-crece-y {
from {
transform: scaleY(0);
}
to {
transform: none;
}
}
.tw-pendiente-icono {
width: 40px;
height: 40px;
color: var(--tono);
background: var(--tono);
border-radius: 12px;
place-items: center;
display: grid;
}
@supports (color: color-mix(in lab, red, red)) {
.tw-pendiente-icono {
background: color-mix(in srgb, var(--tono) 10%, transparent);
}
}
.tw-pendiente-icono svg {
width: 20px;
height: 20px;
}
.tw-pendiente-titulo {
color: var(--color-tinta);
font-size: 14.5px;
font-weight: 600;
line-height: 1.3;
}
.tw-pendiente-titulo b {
font-family: var(--font-serif);
font-variant-numeric: lining-nums tabular-nums;
margin-right: 5px;
font-size: 21px;
font-weight: 500;
}
.tw-pendiente-detalle {
color: var(--color-taupe);
margin-top: 2px;
font-size: 14px;
line-height: 1.35;
}
.tw-pendiente-ir {
color: var(--color-tinta);
white-space: nowrap;
align-items: center;
gap: 6px;
font-size: 14px;
font-weight: 600;
display: inline-flex;
}
.tw-pendiente-ir svg {
width: 16px;
height: 16px;
transition: transform .2s var(--ease-cayla);
}
@media (hover: hover) {
.tw-pendiente:hover .tw-pendiente-ir svg {
transform: translateX(4px);
}
}
.tw-sede {
border-bottom: 1px solid var(--color-sand);
animation: tw-entra .42s var(--ease-cayla) both;
animation-delay: calc(min(var(--i, 0), 8) * 60ms + .36s);
grid-template-columns: 10px minmax(0, 1fr);
align-items: start;
gap: 12px;
padding: 12px 0;
display: grid;
}
.tw-sede:last-child {
border-bottom: 0;
}
.tw-sede-punto {
background: var(--color-tinta-60);
border-radius: 999px;
width: 10px;
height: 10px;
margin-top: 5px;
}
.tw-sede-punto[data-tono="verde"] {
background: var(--color-verde);
}
.tw-sede-punto[data-tono="ambar"] {
background: var(--color-ambar);
}
.tw-sede-punto {
animation: tw-asoma .38s var(--ease-cayla) both;
animation-delay: calc(min(var(--i, 0), 8) * 60ms + .52s);
}
.tw-previa {
gap: 10px;
padding: 16px;
display: grid;
}
.tw-previa-nombre {
font-family: var(--font-serif);
color: var(--color-tinta);
overflow-wrap: anywhere;
transition: color .2s var(--ease-cayla);
font-size: 22px;
line-height: 1.1;
}
.tw-previa-dato {
color: var(--color-tinta);
overflow-wrap: anywhere;
grid-template-columns: 16px minmax(0, 1fr);
gap: 8px;
font-size: 14px;
line-height: 1.35;
display: grid;
}
.tw-previa-dato svg {
width: 14px;
height: 14px;
color: var(--color-taupe);
margin-top: 1px;
}
.tw-previa-dato[data-falta] {
color: var(--color-taupe);
font-style: italic;
}
.tw-previa-boton {
height: 34px;
color: var(--color-crema-fija);
background: var(--color-verde-profundo);
transition: opacity .2s var(--ease-cayla);
border-radius: 999px;
justify-content: center;
align-items: center;
gap: 7px;
padding: 0 14px;
font-size: 12.5px;
font-weight: 600;
display: inline-flex;
}
.tw-previa-boton svg {
width: 14px;
height: 14px;
}
.tw-previa-boton[data-apagado] {
opacity: .4;
}
.tw-previa[data-apagada] {
opacity: .55;
transition: opacity .26s var(--ease-cayla);
}
.tw-linea {
grid-template-columns: repeat(4, minmax(0, 1fr));
gap: 0;
padding: 4px 0 2px;
display: grid;
}
.tw-linea-paso {
text-align: center;
flex-direction: column;
align-items: center;
gap: 6px;
display: flex;
position: relative;
}
.tw-linea-paso:before {
content: "";
background: var(--color-sand);
transform-origin: 0;
width: 100%;
height: 2px;
animation: tw-crece-x .52s var(--ease-cayla) both;
animation-delay: calc(var(--i, 0) * .18s + .2s);
position: absolute;
top: 11px;
left: -50%;
}
.tw-linea-paso:first-child:before {
display: none;
}
.tw-linea-nodo {
border: 2px solid var(--color-tinta);
background: var(--color-papel);
width: 24px;
height: 24px;
color: var(--color-tinta);
animation: tw-asoma .38s var(--ease-cayla) both;
animation-delay: calc(var(--i, 0) * .18s + .38s);
border-radius: 999px;
place-items: center;
display: grid;
position: relative;
}
.tw-linea-nodo svg {
width: 12px;
height: 12px;
}
.tw-linea-nombre {
color: var(--color-tinta);
font-size: 14px;
font-weight: 600;
}
.tw-linea-plazo {
color: var(--color-taupe);
padding: 0 4px;
font-size: 14px;
line-height: 1.3;
}
.tw-linea-plazo b {
font-family: var(--font-serif);
color: var(--color-tinta);
font-variant-numeric: lining-nums tabular-nums;
font-size: 17px;
font-weight: 500;
}
@container tw (max-width: 520px) {
.tw-linea {
grid-template-columns: repeat(2, minmax(0, 1fr));
row-gap: 14px;
}
.tw-linea-paso:nth-child(3):before {
display: none;
}
}
.tw-vitrina {
grid-template-columns: repeat(auto-fill, minmax(168px, 1fr));
gap: 14px;
padding: 16px 20px 20px;
display: grid;
}
@container tw (max-width: 560px) {
.tw-vitrina {
grid-template-columns: repeat(2, minmax(0, 1fr));
gap: 10px;
padding: 12px;
}
}
.tw-carta {
border: 1px solid var(--color-sand);
background: var(--color-papel);
min-width: 0;
animation: tw-tesela .52s var(--ease-cayla) both;
animation-delay: calc(min(var(--i, 0), 18) * 35ms + .12s);
transition: border-color .2s var(--ease-cayla), transform .22s var(--ease-cayla), box-shadow .22s var(--ease-cayla);
border-radius: 14px;
flex-direction: column;
display: flex;
position: relative;
overflow: hidden;
}
@media (hover: hover) {
.tw-carta:hover {
border-color: var(--color-taupe);
transform: translateY(-2px);
box-shadow: 0 14px 28px -20px #1a1a188c;
}
@supports (color: color-mix(in lab, red, red)) {
.tw-carta:hover {
box-shadow: 0 14px 28px -20px color-mix(in srgb, var(--color-sombra) 55%, transparent);
}
}
}
.tw-carta[data-elegida] {
border-color: var(--color-tinta);
box-shadow: 0 0 0 1px var(--color-tinta);
}
.tw-carta-foto {
aspect-ratio: 3 / 4;
background: var(--color-hueso);
cursor: pointer;
width: 100%;
display: block;
position: relative;
}
.tw-carta-foto > :first-child {
position: absolute;
inset: 0;
}
.tw-carta[data-oculta] .tw-carta-foto {
opacity: .5;
transition: opacity .24s var(--ease-cayla);
}
.tw-carta-casilla {
z-index: 1;
cursor: pointer;
background: #fbf8f2e0;
border-radius: 10px;
padding: 6px;
display: grid;
position: absolute;
top: 4px;
left: 4px;
}
@supports (color: color-mix(in lab, red, red)) {
.tw-carta-casilla {
background: color-mix(in srgb, var(--color-papel) 88%, transparent);
}
}
.tw-carta-cuerpo {
flex-direction: column;
gap: 6px;
min-width: 0;
padding: 10px 12px 12px;
display: flex;
}
.tw-carta-nombre {
color: var(--color-tinta);
text-align: left;
text-overflow: ellipsis;
white-space: nowrap;
margin-block: -4px;
padding-block: 4px;
font-size: 15px;
font-weight: 600;
line-height: 1.25;
overflow: hidden;
}
@media (hover: hover) {
.tw-carta-nombre:hover {
color: var(--color-rojo-profundo);
}
}
.tw-carta-stock {
color: var(--color-tinta);
font-variant-numeric: tabular-nums;
flex-wrap: wrap;
gap: 4px 8px;
font-size: 14px;
display: flex;
}
.tw-carta-stock-rotulo, .tw-carta-stock span[data-cero] {
color: var(--color-taupe);
}
.tw-carta-pie {
border-top: 1px solid var(--color-sand);
justify-content: space-between;
align-items: center;
gap: 8px;
margin-top: auto;
padding-top: 4px;
display: flex;
}
.tw-carta-pie > span {
color: var(--color-taupe);
font-size: 14px;
font-weight: 600;
}
.tw-toque:after {
content: "";
position: absolute;
inset: -6px -4px;
}
.tw-toque-casilla {
cursor: pointer;
place-items: center;
min-width: 24px;
min-height: 32px;
margin-block: -6px;
display: grid;
}
.tw-elegir {
grid-template-columns: repeat(auto-fill, minmax(112px, 1fr));
gap: 10px;
display: grid;
}
@media (max-width: 639.98px) {
.tw-elegir {
grid-template-columns: repeat(2, minmax(0, 1fr));
}
}
.tw-elegir-tile {
text-align: left;
background: var(--color-papel);
border: 1px solid var(--color-sand);
width: 100%;
min-width: 0;
transition: border-color .16s var(--ease-cayla), box-shadow .16s var(--ease-cayla), opacity .16s var(--ease-cayla);
border-radius: 12px;
flex-direction: column;
gap: 3px;
padding-bottom: 8px;
display: flex;
overflow: hidden;
}
@media (hover: hover) {
.tw-elegir-tile:hover:not(:disabled) {
border-color: var(--color-taupe);
}
}
.tw-elegir-tile[aria-pressed="true"] {
border-color: var(--color-tinta);
box-shadow: 0 0 0 1px var(--color-tinta);
}
.tw-elegir-tile:disabled {
cursor: not-allowed;
opacity: .45;
}
.tw-elegir-tile[data-no-elegible]:disabled {
opacity: 1;
}
.tw-elegir-tile[data-no-elegible]:disabled .tw-elegir-foto {
opacity: .4;
}
.tw-elegir-tile[data-no-elegible]:disabled .tw-elegir-nombre {
color: var(--color-taupe);
}
.tw-elegir-motivo {
color: var(--color-taupe);
-webkit-line-clamp: 2;
-webkit-box-orient: vertical;
padding: 0 8px;
font-size: 14px;
font-weight: 600;
line-height: 1.25;
display: -webkit-box;
overflow: hidden;
}
.tw-elegir-foto {
aspect-ratio: 3 / 4;
background: var(--color-hueso);
width: 100%;
display: block;
position: relative;
}
.tw-elegir-foto > :first-child {
position: absolute;
inset: 0;
}
.tw-elegir-visto {
z-index: 1;
width: 24px;
height: 24px;
color: var(--color-crema);
background: var(--color-tinta);
opacity: 0;
transition: scale .2s var(--ease-cayla), opacity .16s var(--ease-cayla);
border-radius: 999px;
place-items: center;
display: grid;
position: absolute;
top: 6px;
right: 6px;
scale: .4;
}
.tw-elegir-visto svg {
width: 14px;
height: 14px;
}
.tw-elegir-tile[aria-pressed="true"] .tw-elegir-visto {
opacity: 1;
scale: 1;
}
.tw-elegir-nombre {
color: var(--color-tinta);
text-overflow: ellipsis;
white-space: nowrap;
padding: 4px 8px 0;
font-size: 14px;
font-weight: 600;
line-height: 1.25;
overflow: hidden;
}
.tw-elegir-categoria {
color: var(--color-taupe);
text-overflow: ellipsis;
white-space: nowrap;
padding: 0 8px;
font-size: 14px;
overflow: hidden;
}
.tw-looks {
grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
gap: 14px;
padding: 16px 20px 20px;
display: grid;
}
@container tw (max-width: 560px) {
.tw-looks {
grid-template-columns: minmax(0, 1fr);
padding: 12px;
}
}
.tw-look-collage {
aspect-ratio: 16 / 10;
background: var(--color-hueso);
cursor: pointer;
grid-auto-columns: minmax(0, 1fr);
grid-auto-flow: column;
gap: 3px;
width: 100%;
display: grid;
position: relative;
}
.tw-carta[data-oculta] .tw-look-collage {
opacity: .5;
transition: opacity .24s var(--ease-cayla);
}
.tw-look-collage > span {
position: relative;
overflow: hidden;
}
.tw-look-collage > span > :first-child {
position: absolute;
inset: 0;
}
.tw-look-collage > span[data-no-se-ve] {
opacity: .45;
}
.tw-look-collage > .tw-look-lugar {
z-index: 1;
min-width: 28px;
height: 28px;
font-family: var(--font-serif);
color: var(--color-tinta-fija);
background: #f5f0e8eb;
border-radius: 999px;
place-items: center;
padding: 0 6px;
font-size: 16px;
display: grid;
position: absolute;
top: 8px;
left: 8px;
}
@supports (color: color-mix(in lab, red, red)) {
.tw-look-collage > .tw-look-lugar {
background: color-mix(in srgb, var(--color-crema-fija) 92%, transparent);
}
}
.tw-globo {
background: var(--color-hueso);
width: fit-content;
max-width: 100%;
color: var(--color-tinta);
white-space: pre-line;
overflow-wrap: anywhere;
border-radius: 4px 14px 14px;
padding: 10px 14px;
font-size: 15px;
line-height: 1.45;
position: relative;
}
.tw-globo[data-sin-leer] {
background: #ebe4d8;
}
@supports (color: color-mix(in lab, red, red)) {
.tw-globo[data-sin-leer] {
background: color-mix(in srgb, var(--color-ambar) 12%, var(--color-papel));
}
}
.tw-globo-respuesta {
background: #e7e7de;
border-radius: 14px 4px 14px 14px;
max-width: 92%;
margin-left: auto;
padding: 8px 12px;
}
@supports (color: color-mix(in lab, red, red)) {
.tw-globo-respuesta {
background: color-mix(in srgb, var(--color-verde) 11%, var(--color-papel));
}
}
.tw-globo-respuesta {
color: var(--color-tinta);
white-space: pre-line;
overflow-wrap: anywhere;
animation: tw-entra .42s var(--ease-cayla) both;
font-size: 14px;
line-height: 1.4;
animation-delay: .18s;
}
.tw-globo-respuesta small {
letter-spacing: .08em;
text-transform: uppercase;
color: var(--color-verde-profundo);
margin-bottom: 2px;
font-size: 10.5px;
font-weight: 700;
display: block;
}
.twc-calle {
grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
gap: 16px;
display: grid;
}
@media (max-width: 900px) {
.twc-calle {
scroll-snap-type: x mandatory;
grid-template-columns: none;
grid-auto-columns: 78%;
grid-auto-flow: column;
padding-bottom: 6px;
overflow-x: auto;
}
.twc-calle > * {
scroll-snap-align: start;
}
