}
@supports (color: color-mix(in lab, red, red)) {
.rcc-isla {
--rcc-borde: color-mix(in srgb, var(--color-crema) 14%, transparent);
}
}
.rcc-isla {
top: 0;
left: var(--rcc-lateral);
