@supports (color: color-mix(in lab, red, red)) {
.rcc-isla[data-nivel="3"] .rcc-aurora {
background: radial-gradient(46% 44% at 50% 18%, color-mix(in srgb, var(--rcc-claro) 88%, transparent), transparent 78%), radial-gradient(62% 100% at 50% 0%, color-mix(in srgb, var(--rcc-claro) 46%, transparent), transparent 88%), radial-gradient(28% 90% at 50% 8%, color-mix(in srgb, var(--rcc-claro) 38%, transparent), transparent 92%);
}
}
.rcc-isla[data-nivel="3"][data-fase="viva"] .rcc-aurora {
opacity: 1;
}
.rcc-isla[data-fase="saliendo"] .rcc-aurora, .rcc-isla[data-fase="cerrada"] .rcc-aurora {
