}
}
@keyframes rcc-deriva {
from {
transform: translateX(-26px) scaleX(.94);
}
to {
transform: translateX(26px) scaleX(1.06);
}
}
.rcc-caps {
background: var(--color-tinta);
height: 40px;
color: var(--color-crema);
white-space: nowrap;
box-shadow: 0 0 0 1px var(--rcc-borde), inset 0 1px 0 #f5f0e81f, 0 10px 26px -8px var(--rcc-claro);
border-radius: 20px;
align-items: center;
gap: 12px;
padding: 0 5px 0 14px;
display: flex;
position: relative;
overflow: hidden;
}
@supports (color: color-mix(in lab, red, red)) {
.rcc-caps {
box-shadow: 0 0 0 1px var(--rcc-borde), inset 0 1px 0 color-mix(in srgb, var(--color-crema) 12%, transparent), 0 10px 26px -8px color-mix(in srgb, var(--rcc-claro) 40%, transparent);
}
}
.rcc-caps {
transition: box-shadow .6s var(--ease-cayla), background-color .5s ease;
cursor: pointer;
}
.rcc-isla[data-nivel="2"] .rcc-caps {
box-shadow: 0 0 0 1px var(--rcc-claro), inset 0 1px 0 #f5f0e81f, 0 10px 28px -8px var(--rcc-claro);
}
@supports (color: color-mix(in lab, red, red)) {
.rcc-isla[data-nivel="2"] .rcc-caps {
box-shadow: 0 0 0 1px color-mix(in srgb, var(--rcc-claro) 45%, transparent), inset 0 1px 0 color-mix(in srgb, var(--color-crema) 12%, transparent), 0 10px 28px -8px color-mix(in srgb, var(--rcc-claro) 55%, transparent);
}
}
.rcc-isla[data-nivel="3"] .rcc-caps {
box-shadow: 0 0 0 1px var(--rcc-claro), inset 0 1px 0 #f5f0e81f, 0 14px 36px -8px var(--rcc-claro);
}
@supports (color: color-mix(in lab, red, red)) {
.rcc-isla[data-nivel="3"] .rcc-caps {
box-shadow: 0 0 0 1px color-mix(in srgb, var(--rcc-claro) 65%, transparent), inset 0 1px 0 color-mix(in srgb, var(--color-crema) 12%, transparent), 0 14px 36px -8px color-mix(in srgb, var(--rcc-claro) 75%, transparent);
}
}
.rcc-caps.rcc-ok {
