box-shadow: 0 0 0 1px #0000, 0 10px 26px -8px #48603f99;
}
@supports (color: color-mix(in lab, red, red)) {
.rcc-caps.rcc-ok {
box-shadow: 0 0 0 1px transparent, 0 10px 26px -8px color-mix(in srgb, var(--color-verde) 60%, transparent);
}
}
.rcc-isla[data-fase="naciendo"] .rcc-caps {
animation: rcc-nace .6s var(--ease-cayla) both;
}
.rcc-isla[data-fase="saliendo"] .rcc-caps {
animation: rcc-sale .4s var(--ease-cayla) both;
