@keyframes rcc-nace {
from {
clip-path: inset(0 50% round 20px);
opacity: 0;
transform: translateY(-10px);
}
to {
clip-path: inset(0 round 20px);
opacity: 1;
transform: none;
}
}
@keyframes rcc-sale {
